create table if not exists schedule_daily_overlays(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code() references institutions(institution_code) on delete restrict,overlay_date date not null,operation_group_id uuid not null default gen_random_uuid(),operation_kind text not null check(operation_kind in('COVER','MOVE','SWAP','CANCEL','CREATE','SPLIT','JOIN')),source_absence_lesson_id uuid references absence_lessons(id) on delete cascade,source_schedule_id uuid references teacher_schedule(id) on delete set null,effective_teacher_id uuid references profiles(user_id) on delete restrict,effective_period smallint check(effective_period between 1 and 12),effective_class_id uuid references school_classes(id) on delete restrict,effective_classroom_id uuid references classrooms(id) on delete restrict,effective_subject text,effective_class_name text,status text not null default 'ACTIVE' check(status in('ACTIVE','REVERTED')),payload jsonb not null default '{}'::jsonb,emits_event boolean not null default true,notified_at timestamptz,created_by uuid references profiles(user_id) on delete set null,created_at timestamptz not null default now(),reverted_by uuid references profiles(user_id) on delete set null,reverted_at timestamptz);
create index if not exists idx_schedule_daily_overlays_date on schedule_daily_overlays(institution_code,overlay_date,status);
create index if not exists idx_schedule_daily_overlays_group on schedule_daily_overlays(operation_group_id);
create unique index if not exists uq_schedule_daily_overlay_source_active on schedule_daily_overlays(institution_code,overlay_date,source_schedule_id) where status='ACTIVE' and source_schedule_id is not null;
alter table schedule_daily_overlays enable row level security;
drop policy if exists schedule_daily_overlays_select on schedule_daily_overlays;
create policy schedule_daily_overlays_select on schedule_daily_overlays for select to authenticated using(tenant_row_allowed(institution_code));

create table if not exists schedule_daily_overlay_audit(id uuid primary key default gen_random_uuid(),institution_code text not null default current_tenant_code() references institutions(institution_code) on delete restrict,operation_group_id uuid not null,overlay_date date not null,action text not null check(action in('APPLY','REVERT')),detail jsonb not null default '{}'::jsonb,actor uuid references profiles(user_id) on delete set null,created_at timestamptz not null default now());
alter table schedule_daily_overlay_audit enable row level security;
drop policy if exists schedule_daily_overlay_audit_select on schedule_daily_overlay_audit;
create policy schedule_daily_overlay_audit_select on schedule_daily_overlay_audit for select to authenticated using(tenant_row_allowed(institution_code));

alter table absence_lessons add column if not exists source_schedule_id uuid references teacher_schedule(id) on delete set null;
alter table absence_lessons add column if not exists course_id uuid references course_catalog(id) on delete set null;
alter table absence_lessons add column if not exists classroom_id uuid references classrooms(id) on delete set null;
alter table absence_lessons add column if not exists subgroup_id uuid references class_subgroups(id) on delete set null;
update absence_lessons al set source_schedule_id=ts.id,course_id=ts.course_id,classroom_id=ts.classroom_id,subgroup_id=ts.subgroup_id from teacher_schedule ts where al.source_schedule_id is null and ts.institution_code=al.institution_code and ts.teacher_id=al.teacher_id and ts.weekday=extract(isodow from al.lesson_date)::smallint and ts.period=al.period and ts.active;
alter table substitute_assignments add column if not exists overlay_id uuid references schedule_daily_overlays(id) on delete set null;
alter table substitute_assignments add column if not exists reason text;
alter table substitute_assignments add column if not exists active boolean not null default true;

create or replace function get_schedule_daily_effective_v1(p_date date default current_date) returns table(event_key text,source_schedule_id uuid,source_absence_lesson_id uuid,operation_group_id uuid,operation_kind text,teacher_id uuid,period smallint,class_id uuid,class_name text,course_id uuid,subject text,classroom_id uuid,subgroup_id uuid,is_overlay boolean) language sql stable security definer set search_path=public as $$with base as(select 'S:'||ts.id::text,ts.id,al.id,null::uuid,case when al.id is not null then 'UNCOVERED' else 'BASE' end,ts.teacher_id,ts.period,ts.class_id,ts.class_name,ts.course_id,ts.subject,ts.classroom_id,ts.subgroup_id,false from teacher_schedule ts left join absence_lessons al on al.institution_code=ts.institution_code and al.source_schedule_id=ts.id and al.lesson_date=p_date where ts.active and tenant_row_allowed(ts.institution_code) and ts.weekday=extract(isodow from p_date)::smallint and not exists(select 1 from schedule_daily_overlays o where o.institution_code=ts.institution_code and o.overlay_date=p_date and o.status='ACTIVE' and o.source_schedule_id=ts.id)),ov as(select 'O:'||o.id::text,o.source_schedule_id,o.source_absence_lesson_id,o.operation_group_id,o.operation_kind,o.effective_teacher_id,o.effective_period,coalesce(o.effective_class_id,al.class_id,ts.class_id),coalesce(o.effective_class_name,al.class_name,ts.class_name),coalesce(al.course_id,ts.course_id),coalesce(o.effective_subject,al.subject,ts.subject),coalesce(o.effective_classroom_id,al.classroom_id,ts.classroom_id),coalesce(al.subgroup_id,ts.subgroup_id),true from schedule_daily_overlays o left join absence_lessons al on al.id=o.source_absence_lesson_id left join teacher_schedule ts on ts.id=o.source_schedule_id where o.status='ACTIVE' and o.overlay_date=p_date and o.emits_event and tenant_row_allowed(o.institution_code)) select * from base union all select * from ov$$;

create or replace function get_substitution_transfer_issues_v1(p_teacher uuid,p_date date,p_period smallint,p_classroom uuid) returns text[] language plpgsql stable security definer set search_path=public as $$declare nb uuid;ob uuid;req smallint;avail smallint;allow_transfer boolean;prof uuid;r record;issues text[]:='{}';begin if p_classroom is null then return issues;end if;select building_id into nb from classrooms where id=p_classroom and active;if nb is null then return issues;end if;select id into prof from schedule_time_profiles where active and tenant_row_allowed(institution_code) order by updated_at desc limit 1;if prof is null then return issues;end if;for r in select period,classroom_id from get_schedule_daily_effective_v1(p_date) where teacher_id=p_teacher and classroom_id is not null and period in(p_period-1,p_period+1) loop select building_id into ob from classrooms where id=r.classroom_id and active;if ob is null or ob=nb then continue;end if;req:=get_schedule_building_travel_minutes_v1(ob,nb);if r.period=p_period-1 then select minutes,transfer_allowed into avail,allow_transfer from schedule_period_breaks where time_profile_id=prof and after_period=r.period and tenant_row_allowed(institution_code);else select minutes,transfer_allowed into avail,allow_transfer from schedule_period_breaks where time_profile_id=prof and after_period=p_period and tenant_row_allowed(institution_code);end if;if not coalesce(allow_transfer,false) then issues:=array_append(issues,'BUILDING_TRANSFER_NOT_ALLOWED');elsif coalesce(avail,0)<req then issues:=array_append(issues,'BUILDING_TRANSFER_TIME_INSUFFICIENT');end if;end loop;return issues;end$$;

create or replace function get_substitute_candidates_v4(p_absence_lesson_id uuid) returns table(candidate_user_id uuid,candidate_name text,qualified boolean,duty boolean,weekly_load bigint,monthly_load bigint,hard_reasons text[],feasible boolean,rank_score numeric,reason text) language sql stable security definer set search_path=public as $$with l as(select al.* from absence_lessons al where al.id=p_absence_lesson_id and tenant_row_allowed(al.institution_code)),p as(select pr.user_id,pr.full_name,l.teacher_id,l.lesson_date,l.period,l.course_id,l.classroom_id from l join profiles pr on pr.role='teacher' and tenant_row_allowed(pr.institution_code) where pr.user_id<>l.teacher_id),x as(select p.*,exists(select 1 from teacher_course_assignments ta join class_course_requirements cr on cr.id=ta.class_course_requirement_id where ta.teacher_id=p.user_id and cr.course_id=p.course_id) qualified,exists(select 1 from teacher_duty_assignments d where d.teacher_id=p.user_id and d.duty_date=p.lesson_date and tenant_row_allowed(d.institution_code)) duty,(select count(*) from substitute_assignments s join absence_lessons al on al.id=s.absence_lesson_id where s.substitute_user_id=p.user_id and s.active and tenant_row_allowed(s.institution_code) and al.lesson_date>=date_trunc('week',p.lesson_date)::date and al.lesson_date<(date_trunc('week',p.lesson_date)+interval '7 days')::date)::bigint weekly_load,(select count(*) from substitute_assignments s join absence_lessons al on al.id=s.absence_lesson_id where s.substitute_user_id=p.user_id and s.active and tenant_row_allowed(s.institution_code) and al.lesson_date>=date_trunc('month',p.lesson_date)::date and al.lesson_date<(date_trunc('month',p.lesson_date)+interval '1 month')::date)::bigint monthly_load,array_remove(array[case when exists(select 1 from absences a where a.teacher_id=p.user_id and a.absence_date=p.lesson_date and a.status<>'resolved' and tenant_row_allowed(a.institution_code)) then 'ABSENT' end,case when exists(select 1 from teacher_unavailability u where u.teacher_id=p.user_id and u.weekday=extract(isodow from p.lesson_date)::smallint and u.period=p.period and u.active and tenant_row_allowed(u.institution_code)) then 'UNAVAILABLE' end,case when exists(select 1 from get_schedule_daily_effective_v1(p.lesson_date)e where e.teacher_id=p.user_id and e.period=p.period) then 'TIME_CONFLICT' end],null)::text[]||get_substitution_transfer_issues_v1(p.user_id,p.lesson_date,p.period,p.classroom_id) hard_reasons from p),z as(select x.*,cardinality(hard_reasons)=0 feasible,(case when qualified and duty then 0 when qualified then 100 when duty then 250 else 500 end+weekly_load*20+monthly_load*3)::numeric rank_score from x) select user_id,full_name,qualified,duty,weekly_load,monthly_load,hard_reasons,feasible,rank_score,concat(case when qualified then 'ders yeterliliği doğrulandı' else 'ders yeterliliği doğrulanamadı' end,' · ',case when duty then 'nöbetçi' else 'nöbetçi değil' end,' · hafta ',weekly_load,' · ay ',monthly_load,case when cardinality(hard_reasons)>0 then ' · HARD: '||array_to_string(hard_reasons,',') else '' end) from z order by feasible desc,rank_score,user_id$$;

create or replace function get_event_cover_candidates_v1(p_date date,p_source_schedule_id uuid) returns table(candidate_user_id uuid,candidate_name text,qualified boolean,duty boolean,weekly_load bigint,monthly_load bigint,hard_reasons text[],feasible boolean,rank_score numeric) language sql stable security definer set search_path=public as $$with s as(select ts.* from teacher_schedule ts where ts.id=p_source_schedule_id and ts.active and tenant_row_allowed(ts.institution_code)),p as(select pr.user_id,pr.full_name,s.teacher_id,s.period,s.course_id,s.classroom_id from s join profiles pr on pr.role='teacher' and tenant_row_allowed(pr.institution_code) where pr.user_id<>s.teacher_id),x as(select p.*,exists(select 1 from teacher_course_assignments ta join class_course_requirements cr on cr.id=ta.class_course_requirement_id where ta.teacher_id=p.user_id and cr.course_id=p.course_id) qualified,exists(select 1 from teacher_duty_assignments d where d.teacher_id=p.user_id and d.duty_date=p_date and tenant_row_allowed(d.institution_code)) duty,(select count(*) from substitute_assignments sa join absence_lessons al on al.id=sa.absence_lesson_id where sa.substitute_user_id=p.user_id and sa.active and tenant_row_allowed(sa.institution_code) and al.lesson_date>=date_trunc('week',p_date)::date and al.lesson_date<(date_trunc('week',p_date)+interval '7 day')::date)::bigint weekly_load,(select count(*) from substitute_assignments sa join absence_lessons al on al.id=sa.absence_lesson_id where sa.substitute_user_id=p.user_id and sa.active and tenant_row_allowed(sa.institution_code) and al.lesson_date>=date_trunc('month',p_date)::date and al.lesson_date<(date_trunc('month',p_date)+interval '1 month')::date)::bigint monthly_load,array_remove(array[case when exists(select 1 from absences a where a.teacher_id=p.user_id and a.absence_date=p_date and a.status<>'resolved' and tenant_row_allowed(a.institution_code)) then 'ABSENT' end,case when exists(select 1 from teacher_unavailability u where u.teacher_id=p.user_id and u.weekday=extract(isodow from p_date)::smallint and u.period=p.period and u.active and tenant_row_allowed(u.institution_code)) then 'UNAVAILABLE' end,case when exists(select 1 from get_schedule_daily_effective_v1(p_date)e where e.teacher_id=p.user_id and e.period=p.period) then 'TIME_CONFLICT' end],null)::text[]||get_substitution_transfer_issues_v1(p.user_id,p_date,p.period,p.classroom_id) hard_reasons from p),z as(select x.*,cardinality(hard_reasons)=0 feasible,(case when qualified and duty then 0 when qualified then 100 when duty then 250 else 500 end+weekly_load*20+monthly_load*3)::numeric rank_score from x) select user_id,full_name,qualified,duty,weekly_load,monthly_load,hard_reasons,feasible,rank_score from z order by feasible desc,rank_score,user_id$$;

create or replace function assert_schedule_daily_overlay_hard_v1(p_date date) returns void language plpgsql security definer set search_path=public as $$declare r record;begin if exists(select 1 from get_schedule_daily_effective_v1(p_date)e where e.teacher_id is not null group by e.teacher_id,e.period having count(*)>1) then raise exception 'SUBSTITUTION_TEACHER_CONFLICT';end if;if exists(select 1 from get_schedule_daily_effective_v1(p_date)a join get_schedule_daily_effective_v1(p_date)b on a.event_key<b.event_key and a.period=b.period and a.class_id=b.class_id and a.class_id is not null and(a.subgroup_id is null or b.subgroup_id is null or a.subgroup_id=b.subgroup_id)) then raise exception 'SUBSTITUTION_CLASS_CONFLICT';end if;if exists(select 1 from get_schedule_daily_effective_v1(p_date)e where e.classroom_id is not null group by e.classroom_id,e.period having count(*)>1) then raise exception 'SUBSTITUTION_ROOM_CONFLICT';end if;if exists(select 1 from schedule_room_pools rp join classrooms c on c.room_pool_id=rp.id join get_schedule_daily_effective_v1(p_date)e on e.classroom_id=c.id where rp.active and tenant_row_allowed(rp.institution_code) group by rp.id,rp.max_simultaneous_activities,e.period having count(*)>rp.max_simultaneous_activities) then raise exception 'SUBSTITUTION_ROOM_POOL_SIMULTANEOUS_LIMIT';end if;if exists(select 1 from schedule_room_pools rp join classrooms c on c.room_pool_id=rp.id join get_schedule_daily_effective_v1(p_date)e on e.classroom_id=c.id left join school_classes sc on sc.id=e.class_id where rp.active and rp.capacity is not null and tenant_row_allowed(rp.institution_code) group by rp.id,rp.capacity,e.period having bool_or(e.is_overlay) and bool_or(e.class_id is not null and sc.imported_student_count is null)) then raise exception 'SUBSTITUTION_ROOM_POOL_CAPACITY_UNKNOWN';end if;if exists(select 1 from schedule_room_pools rp join classrooms c on c.room_pool_id=rp.id join get_schedule_daily_effective_v1(p_date)e on e.classroom_id=c.id left join school_classes sc on sc.id=e.class_id where rp.active and rp.capacity is not null and tenant_row_allowed(rp.institution_code) group by rp.id,rp.capacity,e.period having bool_or(e.is_overlay) and sum(coalesce(sc.imported_student_count,0))>rp.capacity) then raise exception 'SUBSTITUTION_ROOM_POOL_CAPACITY_EXCEEDED';end if;for r in select distinct teacher_id,period,classroom_id from get_schedule_daily_effective_v1(p_date) where teacher_id is not null and classroom_id is not null loop if cardinality(get_substitution_transfer_issues_v1(r.teacher_id,p_date,r.period,r.classroom_id))>0 then raise exception '%',(get_substitution_transfer_issues_v1(r.teacher_id,p_date,r.period,r.classroom_id))[1];end if;end loop;end$$;

create or replace function apply_schedule_daily_overlay_v1(p_date date,p_operations jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare op jsonb;k text;gid uuid:=gen_random_uuid();oid uuid;src_id uuid;al_id uuid;al absence_lessons%rowtype;ts teacher_schedule%rowtype;eff_teacher uuid;eff_period smallint;eff_class uuid;eff_room uuid;eff_subject text;eff_class_name text;emit boolean;n int:=0;begin if not(is_manager_or_admin() or has_permission('schedule.edit')) then raise exception 'NOT_AUTHORIZED';end if;if jsonb_typeof(p_operations)<>'array' or jsonb_array_length(p_operations)=0 then raise exception 'OPERATIONS_REQUIRED';end if;perform pg_advisory_xact_lock(hashtext(current_tenant_code()||':'||p_date::text));for op in select * from jsonb_array_elements(p_operations) loop k:=upper(coalesce(op->>'operation_kind',''));if k not in('COVER','MOVE','SWAP','CANCEL','CREATE','SPLIT','JOIN') then raise exception 'INVALID_OPERATION_KIND';end if;src_id:=nullif(op->>'source_schedule_id','')::uuid;al_id:=nullif(op->>'source_absence_lesson_id','')::uuid;if al_id is not null then select * into al from absence_lessons where id=al_id and lesson_date=p_date and tenant_row_allowed(institution_code);if not found then raise exception 'ABSENCE_LESSON_NOT_FOUND';end if;if src_id is null then src_id:=al.source_schedule_id;end if;else al:=null;end if;if src_id is not null then select * into ts from teacher_schedule where id=src_id and active and tenant_row_allowed(institution_code);if not found then raise exception 'SOURCE_SCHEDULE_NOT_FOUND';end if;else ts:=null;end if;if k<>'CREATE' and src_id is null and al_id is null and coalesce((op->>'emit_only')::boolean,false)=false then raise exception 'SOURCE_REQUIRED';end if;eff_teacher:=coalesce(nullif(op->>'effective_teacher_id','')::uuid,case when al_id is not null then al.teacher_id else ts.teacher_id end);eff_period:=coalesce(nullif(op->>'effective_period','')::smallint,case when al_id is not null then al.period else ts.period end);eff_class:=coalesce(nullif(op->>'effective_class_id','')::uuid,case when al_id is not null then al.class_id else ts.class_id end);eff_room:=coalesce(nullif(op->>'effective_classroom_id','')::uuid,case when al_id is not null then al.classroom_id else ts.classroom_id end);eff_subject:=coalesce(nullif(op->>'effective_subject',''),case when al_id is not null then al.subject else ts.subject end);eff_class_name:=coalesce(nullif(op->>'effective_class_name',''),case when al_id is not null then al.class_name else ts.class_name end);emit:=coalesce((op->>'emits_event')::boolean,k<>'CANCEL');if k='COVER' then if al_id is null or eff_teacher is null then raise exception 'COVER_REQUIRES_ABSENCE_AND_TEACHER';end if;if not exists(select 1 from get_substitute_candidates_v4(al_id)c where c.candidate_user_id=eff_teacher and c.feasible) then raise exception 'SUBSTITUTE_NOT_FEASIBLE';end if;end if;insert into schedule_daily_overlays(institution_code,overlay_date,operation_group_id,operation_kind,source_absence_lesson_id,source_schedule_id,effective_teacher_id,effective_period,effective_class_id,effective_classroom_id,effective_subject,effective_class_name,emits_event,payload,created_by) values(current_tenant_code(),p_date,gid,k,al_id,src_id,case when emit then eff_teacher else null end,case when emit then eff_period else null end,case when emit then eff_class else null end,case when emit then eff_room else null end,case when emit then eff_subject else null end,case when emit then eff_class_name else null end,emit,coalesce(op->'payload','{}'::jsonb),auth.uid()) returning id into oid;if k='COVER' then insert into substitute_assignments(absence_lesson_id,substitute_user_id,assigned_by,institution_code,overlay_id,reason,approval_status,approved_by,approved_at) values(al_id,eff_teacher,auth.uid(),current_tenant_code(),oid,coalesce(op->>'reason','V4 canonical cover'),'approved',auth.uid(),now()) on conflict(absence_lesson_id) do update set substitute_user_id=excluded.substitute_user_id,assigned_by=excluded.assigned_by,assigned_at=now(),overlay_id=excluded.overlay_id,reason=excluded.reason,approval_status='changed',approved_by=excluded.approved_by,approved_at=excluded.approved_at;end if;n:=n+1;end loop;perform assert_schedule_daily_overlay_hard_v1(p_date);update absences a set status='planned' where a.absence_date=p_date and tenant_row_allowed(a.institution_code) and not exists(select 1 from absence_lessons al left join substitute_assignments sa on sa.absence_lesson_id=al.id and sa.active where al.teacher_id=a.teacher_id and al.lesson_date=a.absence_date and tenant_row_allowed(al.institution_code) and sa.id is null);return jsonb_build_object('operation_group_id',gid,'operations',n);end$$;

create or replace function revert_schedule_daily_overlay_v1(p_operation_group_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare d date;n int;begin if not(is_manager_or_admin() or has_permission('schedule.edit')) then raise exception 'NOT_AUTHORIZED';end if;select overlay_date into d from schedule_daily_overlays where operation_group_id=p_operation_group_id and status='ACTIVE' and tenant_row_allowed(institution_code) limit 1;if d is null then raise exception 'ACTIVE_OVERLAY_GROUP_NOT_FOUND';end if;perform pg_advisory_xact_lock(hashtext(current_tenant_code()||':'||d::text));update substitute_assignments sa set active=false,approval_status='rejected',approved_by=auth.uid(),approved_at=now() where sa.active and sa.overlay_id in(select id from schedule_daily_overlays where operation_group_id=p_operation_group_id and tenant_row_allowed(institution_code));update schedule_daily_overlays set status='REVERTED',reverted_by=auth.uid(),reverted_at=now() where operation_group_id=p_operation_group_id and status='ACTIVE' and tenant_row_allowed(institution_code);get diagnostics n=row_count;update absences a set status='open' where a.absence_date=d and tenant_row_allowed(a.institution_code) and exists(select 1 from absence_lessons al where al.teacher_id=a.teacher_id and al.lesson_date=d and tenant_row_allowed(al.institution_code) and not exists(select 1 from substitute_assignments sa where sa.absence_lesson_id=al.id and sa.active));perform assert_schedule_daily_overlay_hard_v1(d);insert into schedule_daily_overlay_audit(institution_code,operation_group_id,overlay_date,action,detail,actor) values(current_tenant_code(),p_operation_group_id,d,'REVERT',jsonb_build_object('rows',n),auth.uid());return jsonb_build_object('reverted',n,'operation_group_id',p_operation_group_id);end$$;

create or replace function assign_substitutes_for_day_v4(p_date date default current_date) returns jsonb language plpgsql security definer set search_path=public as $$declare l record;c record;r jsonb;assigned int:=0;uncovered int:=0;begin if not is_manager_or_admin() then raise exception 'NOT_AUTHORIZED';end if;for l in select al.id from absence_lessons al where al.lesson_date=p_date and tenant_row_allowed(al.institution_code) and not exists(select 1 from substitute_assignments sa where sa.absence_lesson_id=al.id and sa.active) order by al.period,al.class_name loop select * into c from get_substitute_candidates_v4(l.id) where feasible order by rank_score,candidate_user_id limit 1;if found then r:=apply_schedule_daily_overlay_v1(p_date,jsonb_build_array(jsonb_build_object('operation_kind','COVER','source_absence_lesson_id',l.id,'effective_teacher_id',c.candidate_user_id,'reason','V4 direct cover')));assigned:=assigned+1;else uncovered:=uncovered+1;end if;end loop;return jsonb_build_object('assigned',assigned,'uncovered',uncovered);end$$;

create or replace function suggest_substitution_chains_v4(p_date date default current_date,p_limit int default 20) returns table(absence_lesson_id uuid,period smallint,class_name text,subject text,primary_teacher_id uuid,primary_teacher_name text,cover_teacher_id uuid,cover_teacher_name text,total_score numeric,operations jsonb) language sql stable security definer set search_path=public as $$with lessons as(select al.* from absence_lessons al where al.lesson_date=p_date and tenant_row_allowed(al.institution_code) and not exists(select 1 from substitute_assignments sa where sa.absence_lesson_id=al.id and sa.active)),a as(select l.*,c.candidate_user_id a_id,c.candidate_name a_name,c.rank_score a_score from lessons l cross join lateral get_substitute_candidates_v4(l.id)c where not c.feasible and c.hard_reasons=array['TIME_CONFLICT']::text[]),busy as(select a.*,e.source_schedule_id busy_schedule from a join lateral(select e.source_schedule_id from get_schedule_daily_effective_v1(p_date)e where e.teacher_id=a.a_id and e.period=a.period and not e.is_overlay and e.source_schedule_id is not null limit 1)e on true),b as(select busy.*,c.candidate_user_id b_id,c.candidate_name b_name,c.rank_score b_score from busy cross join lateral get_event_cover_candidates_v1(p_date,busy.busy_schedule)c where c.feasible and c.candidate_user_id<>busy.teacher_id) select id,period,class_name,subject,a_id,a_name,b_id,b_name,a_score+b_score,jsonb_build_array(jsonb_build_object('operation_kind','SWAP','source_schedule_id',busy_schedule,'effective_teacher_id',b_id,'effective_period',period,'payload',jsonb_build_object('chain_role','release_primary')),jsonb_build_object('operation_kind','COVER','source_absence_lesson_id',id,'effective_teacher_id',a_id,'reason','V4 chain cover','payload',jsonb_build_object('chain_role','cover_absence'))) from b order by a_score+b_score,id limit greatest(1,p_limit)$$;

create or replace function apply_substitution_chain_v4(p_absence_lesson_id uuid,p_primary_teacher_id uuid,p_cover_teacher_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare d date;per smallint;busy uuid;ops jsonb;begin if not is_manager_or_admin() then raise exception 'NOT_AUTHORIZED';end if;select lesson_date,period into d,per from absence_lessons where id=p_absence_lesson_id and tenant_row_allowed(institution_code);if d is null then raise exception 'ABSENCE_LESSON_NOT_FOUND';end if;select e.source_schedule_id into busy from get_schedule_daily_effective_v1(d)e where e.teacher_id=p_primary_teacher_id and e.period=per and not e.is_overlay and e.source_schedule_id is not null limit 1;if busy is null then raise exception 'PRIMARY_TEACHER_NOT_BUSY_ON_BASE_EVENT';end if;if not exists(select 1 from get_event_cover_candidates_v1(d,busy)c where c.candidate_user_id=p_cover_teacher_id and c.feasible) then raise exception 'CHAIN_COVER_TEACHER_NOT_FEASIBLE';end if;ops:=jsonb_build_array(jsonb_build_object('operation_kind','SWAP','source_schedule_id',busy,'effective_teacher_id',p_cover_teacher_id,'effective_period',per,'payload',jsonb_build_object('chain_role','release_primary')),jsonb_build_object('operation_kind','COVER','source_absence_lesson_id',p_absence_lesson_id,'effective_teacher_id',p_primary_teacher_id,'reason','V4 chain cover','payload',jsonb_build_object('chain_role','cover_absence')));return apply_schedule_daily_overlay_v1(d,ops);end$$;

create or replace function get_substitution_day_health_v4(p_date date default current_date) returns table(absence_lessons bigint,covered bigint,uncovered bigint,active_overlays bigint,direct_covers bigint,chain_operations bigint,pending_notifications bigint,reverted_groups bigint) language sql stable security definer set search_path=public as $$select(select count(*) from absence_lessons al where al.lesson_date=p_date and tenant_row_allowed(al.institution_code)),(select count(*) from absence_lessons al where al.lesson_date=p_date and tenant_row_allowed(al.institution_code) and exists(select 1 from substitute_assignments sa where sa.absence_lesson_id=al.id and sa.active)),(select count(*) from absence_lessons al where al.lesson_date=p_date and tenant_row_allowed(al.institution_code) and not exists(select 1 from substitute_assignments sa where sa.absence_lesson_id=al.id and sa.active)),(select count(*) from schedule_daily_overlays o where o.overlay_date=p_date and o.status='ACTIVE' and tenant_row_allowed(o.institution_code)),(select count(*) from schedule_daily_overlays o where o.overlay_date=p_date and o.status='ACTIVE' and o.operation_kind='COVER' and coalesce(o.payload->>'chain_role','')='' and tenant_row_allowed(o.institution_code)),(select count(*) from schedule_daily_overlays o where o.overlay_date=p_date and o.status='ACTIVE' and coalesce(o.payload->>'chain_role','')<>'' and tenant_row_allowed(o.institution_code)),(select count(*) from schedule_daily_overlays o where o.overlay_date=p_date and o.status='ACTIVE' and o.emits_event and o.effective_teacher_id is not null and o.notified_at is null and tenant_row_allowed(o.institution_code)),(select count(distinct o.operation_group_id) from schedule_daily_overlays o where o.overlay_date=p_date and o.status='REVERTED' and tenant_row_allowed(o.institution_code))$$;

create or replace function normalize_substitute_assignment_active_v1() returns trigger language plpgsql as $$begin if new.overlay_id is not null and new.approval_status in('approved','changed') then new.active:=true;end if;return new;end$$;
drop trigger if exists trg_normalize_substitute_assignment_active_v1 on substitute_assignments;
create trigger trg_normalize_substitute_assignment_active_v1 before insert or update on substitute_assignments for each row execute function normalize_substitute_assignment_active_v1();
create or replace function audit_schedule_daily_overlay_v1() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' then insert into schedule_daily_overlay_audit(institution_code,operation_group_id,overlay_date,action,detail,actor) values(new.institution_code,new.operation_group_id,new.overlay_date,'APPLY',jsonb_build_object('overlay_id',new.id,'kind',new.operation_kind),new.created_by);end if;return new;end$$;
drop trigger if exists trg_audit_schedule_daily_overlay_v1 on schedule_daily_overlays;
create trigger trg_audit_schedule_daily_overlay_v1 after insert on schedule_daily_overlays for each row execute function audit_schedule_daily_overlay_v1();